<script setup>
import {ref,onMounted,onUnmounted} from 'vue';import {watchAllReports} from '../services/data';import {httpsCallable} from 'firebase/functions';import {functions} from '../firebase';
const props=defineProps(['user','profile']);const reports=ref([]);const busy=ref({});let stop;onMounted(()=>stop=watchAllReports(v=>reports.value=v));onUnmounted(()=>stop?.());
async function act(r,type){busy.value[r.id]=true;try{await httpsCallable(functions,'moderate')({targetUid:r.targetUid,type,targetId:r.targetId,reason:`Rapor: ${r.reason||''}`});alert('Moderasyon işlemi kaydedildi.')}catch(e){alert(e.message)}finally{busy.value[r.id]=false}}
</script><template><h1>🛡 Moderatör Paneli</h1><p class="muted">Açık raporları incele ve kademeli yaptırımları uygula.</p><div class="card" v-for="r in reports" :key="r.id"><div class="space"><div><b>{{r.targetType}}</b><span class="muted"> · hedef: {{r.targetUid}}</span></div><span class="tag">{{r.status}}</span></div><p>{{r.reason||'Sebep belirtilmemiş.'}}</p><div class="row"><button class="btn secondary" :disabled="busy[r.id]" @click="act(r,'WARNING')">⚠ Uyarı</button><button class="btn secondary" :disabled="busy[r.id]" @click="act(r,'MUTE_1_24H')">🔇 Mute 1-24s</button><button class="btn secondary" :disabled="busy[r.id]" @click="act(r,'BAN_1_14D')">⛔ Ban 1-14g</button><button class="btn secondary" :disabled="busy[r.id]" @click="act(r,'CONTENT_DELETE')">🗑 İçerik sil</button></div></div><div v-if="!reports.length" class="card empty">Açık rapor yok.</div></template>
